//! OUTPUT native custom error state and live ValidityState.
use super::*;
fn fixture()->(Document,Forms,Page){let mut d=crate::html::parse("<html><body><form id=owner><input id=field name=field value=seed></form><output id=output form=owner>default</output></body></html>");d.scripting_enabled=true;let mut f=Forms::new(&d);let mut p=Page::new();let location=crate::navigation::address("https://output-validity-state.test/source",&crate::navigation::Location::home()).unwrap();p.set_location(&location);p.set_resource_base(&location);assert_eq!(p.start(&mut d,&mut f,&[]).errors,0);(d,f,p)}
fn run(d:&mut Document,f:&mut Forms,p:&mut Page,s:&str){p.runtime.execute(s,&mut Bridge{doc:d,forms:f,state:&mut p.state}).unwrap();}
#[test]
fn output_validity_state_live_same_object_custom_error_and_flags(){let(mut d,mut f,mut p)=fixture();run(&mut d,&mut f,&mut p,r#"var o=document.getElementById('output'),v=o.validity;if(!v||v!==o.validity||Object.getPrototypeOf(v)!==ValidityState.prototype||!(v instanceof ValidityState)||v.customError!==false||v.valid!==true)throw 'native validity identity';for(var key of ['valueMissing','typeMismatch','patternMismatch','tooLong','tooShort','rangeUnderflow','rangeOverflow','stepMismatch','badInput'])if(v[key]!==false)throw 'inapplicable output constraint';if(o.setCustomValidity('A\ud800z\r\nB\rC')!==undefined||v.customError!==true||v.valid!==false||o.validity!==v||o.willValidate!==false||o.validationMessage!==''||o.checkValidity()!==true||o.reportValidity()!==true)throw 'live output custom error';o.setCustomValidity('');if(v.customError!==false||v.valid!==true)throw 'clear custom error';"#);}
#[test]
fn output_validity_state_conversion_abrupt_and_non_candidate_events(){let(mut d,mut f,mut p)=fixture();run(&mut d,&mut f,&mut p,r#"var o=document.getElementById('output'),v=o.validity,count=0,invalid=0;o.addEventListener('invalid',function(){invalid++;});o.setCustomValidity({toString:function(){count++;o.value='current';return 'error';}});if(count!==1||v.customError!==true||o.value!=='current'||o.defaultValue!=='default')throw 'once conversion';var caught=false;try{o.setCustomValidity({toString:function(){throw 'abrupt';}});}catch(e){caught=e==='abrupt';}if(!caught||v.valid!==false)throw 'abrupt custom error';caught=false;try{o.setCustomValidity(Symbol());}catch(e){caught=e instanceof TypeError;}if(!caught||v.customError!==true)throw 'symbol custom error';o.setCustomValidity(null);if(v.customError!==true||o.checkValidity()!==true||o.reportValidity()!==true||o.validationMessage!==''||invalid)throw 'noncandidate custom error';o.setCustomValidity('');if(v.valid!==true)throw 'custom recovery';"#);}
#[test]
fn output_validity_state_inert_clone_fresh_adoption_preserves_live_identity(){let(mut d,mut f,mut p)=fixture();run(&mut d,&mut f,&mut p,r#"var doc=document.implementation.createHTMLDocument('source'),o=doc.createElement('output');o.textContent='seed';o.value='current';o.setCustomValidity('custom');var v=o.validity,c=o.cloneNode(true),target=document.implementation.createHTMLDocument('target');target.adoptNode(o);if(o.validity!==v||v.customError!==true||v.valid!==false||c.validity===v||c.validity.customError!==false||c.validity.valid!==true||o.ownerDocument!==target||o.value!=='current'||o.defaultValue!=='seed'||c.defaultValue!=='current')throw 'native custom-state lifecycle';c.setCustomValidity('copy');o.setCustomValidity('');if(c.validity.customError!==true||v.customError!==false||v.valid!==true)throw 'independent custom state';"#);}

#[test]
fn output_validity_state_canonical_readonly_descriptors_brands_and_required_argument(){let(mut d,mut f,mut p)=fixture();run(&mut d,&mut f,&mut p,r#"var o=document.getElementById('output'),v=o.validity,p=HTMLOutputElement.prototype,a=Object.getOwnPropertyDescriptor(p,'validity'),method=p.setCustomValidity;if(!a.enumerable||!a.configurable||a.set!==undefined||a.get.name!=='get validity'||a.get.length!==0||method.name!=='setCustomValidity'||method.length!==1||Object.hasOwn(o,'validity'))throw 'output validity descriptor';var keys=['valueMissing','typeMismatch','patternMismatch','tooLong','tooShort','rangeUnderflow','rangeOverflow','stepMismatch','badInput','customError','valid'];for(var key of keys){var descriptor=Object.getOwnPropertyDescriptor(ValidityState.prototype,key);if(!descriptor||!descriptor.enumerable||!descriptor.configurable||descriptor.set!==undefined||descriptor.get.name!=='get '+key||descriptor.get.length!==0||Object.hasOwn(v,key))throw 'readonly validity flags';var expected=key==='valid';v[key]='author';var caught=false;try{(function(){'use strict';v[key]='author';})();}catch(e){caught=e instanceof TypeError;}if(!caught||v[key]!==expected||Object.hasOwn(v,key))throw 'readonly validity assignment';for(var bad of [{},Object.create(ValidityState.prototype),o,document.getElementById('field'),o.htmlFor]){caught=false;try{descriptor.get.call(bad);}catch(e){caught=e instanceof TypeError;}if(!caught)throw 'genuine validity brand';}}var caught=false;try{new ValidityState();}catch(e){caught=e instanceof TypeError;}if(!caught)throw 'illegal validity constructor';var calls=0;for(var bad of [null,{},v,Object.create(p),document.getElementById('field')]){caught=false;try{method.call(bad,{toString:function(){calls++;return 'bad';}});}catch(e){caught=e instanceof TypeError;}if(!caught||calls)throw 'method brand before conversion';}o.setCustomValidity('existing');caught=false;try{o.setCustomValidity();}catch(e){caught=e instanceof TypeError;}if(!caught||v.customError!==true)throw 'required custom error argument';"#);}
#[test]
fn output_validity_state_author_shadows_restore_and_saved_native_views(){let(mut d,mut f,mut p)=fixture();run(&mut d,&mut f,&mut p,r#"var o=document.getElementById('output'),v=o.validity,proto=HTMLOutputElement.prototype,a=Object.getOwnPropertyDescriptor(proto,'validity'),setter=proto.setCustomValidity,valid=Object.getOwnPropertyDescriptor(ValidityState.prototype,'valid');Object.defineProperty(o,'validity',{value:'own',configurable:true});o.setCustomValidity='author';if(o.validity!=='own'||a.get.call(o)!==v)throw 'own validity shadow';setter.call(o,'error');if(valid.get.call(v)!==false)throw 'native custom authority';delete o.validity;delete o.setCustomValidity;Object.defineProperty(ValidityState.prototype,'valid',{value:'prototype',configurable:true});if(v.valid!=='prototype'||valid.get.call(v)!==false)throw 'prototype flag shadow';delete ValidityState.prototype.valid;if(v.valid!==undefined||valid.get.call(v)!==false)throw 'deleted flag';Object.defineProperty(ValidityState.prototype,'valid',valid);Object.defineProperty(v,'customError',{value:'own',configurable:true});setter.call(o,'');if(v.valid!==true||v.customError!=='own')throw 'native flag independence';delete v.customError;if(v.customError!==false||o.validity!==v)throw 'restored native state';"#);}
#[test]
fn output_validity_state_saved_child_origin_precedes_conversion_and_recovers(){let(mut d,mut f,mut p)=fixture();run(&mut d,&mut f,&mut p,r#"var o=document.getElementById('output'),v=o.validity,frame=document.createElement('iframe');frame.hidden=true;document.body.appendChild(frame);var proto=frame.contentWindow.HTMLOutputElement.prototype,get=Object.getOwnPropertyDescriptor(proto,'validity').get,set=proto.setCustomValidity,valid=Object.getOwnPropertyDescriptor(frame.contentWindow.ValidityState.prototype,'valid').get,calls=0;set.call(o,'custom');if(get.call(o)!==v||valid.call(v)!==false)throw 'child canonical state';"#);let before=format!("{:?}",d.nodes);let state=(p.state.retained,p.state.dom_commits,p.state.output_custom_errors.len());p.set_location(&crate::navigation::address("https://foreign-output-validity.test/",&crate::navigation::Location::home()).unwrap());for source in ["get.call(o);","valid.call(v);","set.call(o,{toString:function(){calls++;return 'bad';}});"]{p.begin_job();let e=p.runtime.execute(source,&mut Bridge{doc:&mut d,forms:&mut f,state:&mut p.state}).unwrap_err();assert!(e.contains("origin")||e.contains("Security"),"{e}");assert_eq!(format!("{:?}",d.nodes),before);assert_eq!((p.state.retained,p.state.dom_commits,p.state.output_custom_errors.len()),state);}p.set_location(&crate::navigation::address("https://output-validity-state.test/source",&crate::navigation::Location::home()).unwrap());p.begin_job();run(&mut d,&mut f,&mut p,"if(calls||valid.call(v)!==false)throw 'origin before conversion';set.call(o,'');if(valid.call(v)!==true||get.call(o)!==v)throw 'fresh validity recovery';");}
#[test]
fn output_validity_state_exact_normalized_native_storage_and_clear(){let(mut d,mut f,mut p)=fixture();run(&mut d,&mut f,&mut p,r#"var o=document.getElementById('output');o.setCustomValidity('A\ud800z\r\nB\rC\0\udfff');"#);let n=(0..d.nodes.len()).find(|&n|d.dom_attr(n,"id").is_some_and(|v|v.as_str()=="output")).unwrap();let object=node_handle(n);let value=p.state.output_custom_errors.get(&object).unwrap();assert_eq!(value.code_units().collect::<Vec<_>>(),vec![65,0xd800,122,10,66,10,67,0,0xdfff]);let old=value.capacity();let retained=p.state.retained;run(&mut d,&mut f,&mut p,"o.setCustomValidity('');if(o.validity.customError!==false||o.validity.valid!==true)throw 'empty clear';");assert!(p.state.output_custom_errors.get(&object).is_none());assert_eq!(p.state.retained,retained-old);}
#[test]
fn output_validity_state_writer_limits_preserve_authority_and_recover(){for inert in [false,true]{for mode in 0..5{let(mut d,mut f,mut p)=fixture();run(&mut d,&mut f,&mut p,if inert{"var doc=document.implementation.createHTMLDocument('inert'),o=doc.createElement('output');o.textContent='seed';o.value='current';o.setCustomValidity('existing');var v=o.validity;"}else{"var o=document.getElementById('output');o.value='current';o.setCustomValidity('existing');var v=o.validity;"});p.state.rebuild(&d).unwrap();let before=format!("{:?}",d.nodes);let state=(p.state.retained,p.state.dom_commits,p.state.attributes.len(),p.state.detached_nodes.clone(),p.state.output_defaults.len(),p.state.output_custom_errors.len());let limit=p.state.retained_limit;let strings=p.state.limits.host.string_bytes;p.begin_job();match mode{0=>p.state.host_work=0,1=>p.state.copy_work=0,2=>p.state.retained_limit=p.state.retained,3=>p.state.limits.host.string_bytes=1,_=>p.state.execution_deadline=Some(Instant::now())};let e=p.runtime.execute(r#"o.setCustomValidity('new A\ud800z\r\nB\udfff');"#,&mut Bridge{doc:&mut d,forms:&mut f,state:&mut p.state}).unwrap_err();assert!(e.contains("work")||e.contains("allowance")||e.contains("limit")||e.contains("bound"),"{inert}/{mode}: {e}");assert_eq!(format!("{:?}",d.nodes),before);assert_eq!((p.state.retained,p.state.dom_commits,p.state.attributes.len(),p.state.detached_nodes.clone(),p.state.output_defaults.len(),p.state.output_custom_errors.len()),state);p.state.retained_limit=limit;p.state.limits.host.string_bytes=strings;p.state.execution_deadline=None;p.begin_job();run(&mut d,&mut f,&mut p,"if(o.validity!==v||v.customError!==true||v.valid!==false||o.value!=='current')throw 'atomic custom error refusal';o.setCustomValidity('');if(v.valid!==true||v.customError!==false)throw 'fresh custom error recovery';");}}}

#[test]
fn output_validity_state_first_index_growth_refuses_joint_peak_and_recovers(){for prior in [0,4]{let(mut d,mut f,mut p)=fixture();run(&mut d,&mut f,&mut p,&format!("var doc=document.implementation.createHTMLDocument('source'),outs=[];for(var i=0;i<{prior};i++){{var x=doc.createElement('output');x.setCustomValidity('seed');outs.push(x);}}var o=doc.createElement('output'),v=o.validity;"));p.state.rebuild(&d).unwrap();let before=format!("{:?}",d.nodes);let state=(p.state.retained,p.state.dom_commits,p.state.output_custom_errors.len(),p.state.output_custom_errors.storage_bytes());let limit=p.state.retained_limit;p.state.retained_limit=p.state.retained+8;p.begin_job();let error=p.runtime.execute("o.setCustomValidity('next');",&mut Bridge{doc:&mut d,forms:&mut f,state:&mut p.state}).unwrap_err();assert!(error.contains("storage")||error.contains("allowance"),"{prior}: {error}");assert_eq!(format!("{:?}",d.nodes),before);assert_eq!((p.state.retained,p.state.dom_commits,p.state.output_custom_errors.len(),p.state.output_custom_errors.storage_bytes()),state);p.state.retained_limit=limit;p.begin_job();run(&mut d,&mut f,&mut p,"if(o.validity!==v||v.valid!==true||v.customError!==false)throw 'unpublished native error';for(var x of outs)if(x.validity.customError!==true||x.validity.valid!==false)throw 'existing errors changed';o.setCustomValidity('next');if(v.customError!==true||v.valid!==false)throw 'fresh native error index recovery';");assert_eq!(p.state.output_custom_errors.len(),prior+1);}}
